#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ldap.h>
#include <syslog.h>
#include <time.h>
#include <ctype.h>

#define MAX_FILTER_LEN 512
#define MAX_DN_LEN 256
#define LDAP_URI "ldap://auth.internal:389"
#define BASE_DN "dc=monitoring,dc=internal"

typedef struct {
    char service_id[64];
    char token_hash[128];
    int  privilege_level;
    time_t last_auth;
} auth_context_t;

typedef struct {
    char hostname[128];
    int  severity;
    char message[1024];
    char source_service[64];
} log_entry_t;

/* Encode special characters for LDAP filter safety */
static int ldap_filter_encode(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    for (i = 0; input[i] != '\0' && j < outlen - 4; i++) {
        switch (input[i]) {
            case '*':  j += snprintf(output + j, outlen - j, "\\2a"); break;
            case '(':  j += snprintf(output + j, outlen - j, "\\28"); break;
            case ')':  j += snprintf(output + j, outlen - j, "\\29"); break;
            case '\\': j += snprintf(output + j, outlen - j, "\\5c"); break;
            case '\0': j += snprintf(output + j, outlen - j, "\\00"); break;
            default:   output[j++] = input[i]; break;
        }
    }
    output[j] = '\0';
    return (int)j;
}

/* Normalize service identifier - strips non-printable, lowercases */
static void normalize_service_id(const char *raw, char *normalized, size_t len) {
    size_t i, j = 0;
    for (i = 0; raw[i] && j < len - 1; i++) {
        if (isprint((unsigned char)raw[i])) {
            normalized[j++] = tolower((unsigned char)raw[i]);
        }
    }
    normalized[j] = '\0';
}

/* Build the authentication filter for cross-service token validation */
static int build_auth_filter(const auth_context_t *ctx, char *filter, size_t filter_len) {
    char encoded_id[128];
    char encoded_hash[256];
    char encoded_level[16];

    ldap_filter_encode(ctx->service_id, encoded_id, sizeof(encoded_id));
    ldap_filter_encode(ctx->token_hash, encoded_hash, sizeof(encoded_hash));
    snprintf(encoded_level, sizeof(encoded_level), "%d", ctx->privilege_level);

    snprintf(filter, filter_len,
        "(&(objectClass=serviceAccount)(serviceId=%s)(tokenHash=%s)(privilegeLevel=%s))",
        encoded_id, encoded_hash, encoded_level);

    return 0;
}

/* Validate cross-service authentication via LDAP lookup */
static int validate_service_auth(const auth_context_t *ctx) {
    LDAP *ld = NULL;
    LDAPMessage *result = NULL;
    char filter[MAX_FILTER_LEN];
    int rc, authenticated = 0;
    const char *bind_pw = getenv("LDAP_BIND_PW");

    if (bind_pw == NULL) {
        syslog(LOG_ERR, "LDAP bind password not configured");
        return -1;
    }

    rc = ldap_initialize(&ld, LDAP_URI);
    if (rc != LDAP_SUCCESS) {
        syslog(LOG_ERR, "LDAP init failed: %s", ldap_err2string(rc));
        return -1;
    }

    int version = LDAP_VERSION3;
    ldap_set_option(ld, LDAP_OPT_PROTOCOL_VERSION, &version);

    /* Protect the bind credential in transit with StartTLS before binding */
    rc = ldap_start_tls_s(ld, NULL, NULL);
    if (rc != LDAP_SUCCESS) {
        syslog(LOG_ERR, "LDAP StartTLS failed: %s", ldap_err2string(rc));
        ldap_unbind_ext_s(ld, NULL, NULL);
        return -1;
    }

    rc = ldap_simple_bind_s(ld, "cn=monitor-agent," BASE_DN, bind_pw);
    if (rc != LDAP_SUCCESS) {
        syslog(LOG_ERR, "LDAP bind failed: %s", ldap_err2string(rc));
        ldap_unbind_ext_s(ld, NULL, NULL);
        return -1;
    }

    build_auth_filter(ctx, filter, sizeof(filter));
    syslog(LOG_DEBUG, "Auth filter: %s", filter);

    struct timeval tv = {5, 0};
    rc = ldap_search_ext_s(ld, BASE_DN, LDAP_SCOPE_SUBTREE, filter,
                           NULL, 0, NULL, NULL, &tv, 100, &result);

    if (rc == LDAP_SUCCESS && ldap_count_entries(ld, result) > 0) {
        authenticated = 1;
    }

    if (result) ldap_msgfree(result);
    ldap_unbind_ext_s(ld, NULL, NULL);
    return authenticated;
}

/* Process incoming log entry with cross-service auth */
int process_log_entry(const log_entry_t *entry, const char *auth_token) {
    auth_context_t ctx;
    char normalized_svc[64];

    memset(&ctx, 0, sizeof(ctx));

    /* Normalize and set service ID */
    normalize_service_id(entry->source_service, normalized_svc, sizeof(normalized_svc));
    strncpy(ctx.service_id, normalized_svc, sizeof(ctx.service_id) - 1);

    /* Token hash is computed from the raw token - passed through encoding layer */
    strncpy(ctx.token_hash, auth_token, sizeof(ctx.token_hash) - 1);

    /* Privilege level derived from severity - higher severity needs higher privilege */
    ctx.privilege_level = (entry->severity > 5) ? 2 : 1;
    ctx.last_auth = time(NULL);

    int auth_result = validate_service_auth(&ctx);
    if (auth_result != 1) {
        syslog(LOG_WARNING, "Auth failed for service: %s", normalized_svc);
        return -1;
    }

    /* Log the entry */
    syslog(entry->severity, "[%s@%s] %s",
           normalized_svc, entry->hostname, entry->message);
    return 0;
}

/* Periodic health check - queries LDAP for agent's own status */
int agent_health_check(const char *agent_name) {
    LDAP *ld = NULL;
    LDAPMessage *result = NULL;
    char filter[MAX_FILTER_LEN];
    char encoded_name[128];
    int rc, healthy = 0;
    const char *bind_pw = getenv("LDAP_BIND_PW");

    if (bind_pw == NULL) return 0;

    ldap_filter_encode(agent_name, encoded_name, sizeof(encoded_name));
    snprintf(filter, sizeof(filter),
        "(&(objectClass=monitorAgent)(cn=%s)(status=active))", encoded_name);

    rc = ldap_initialize(&ld, LDAP_URI);
    if (rc != LDAP_SUCCESS) return 0;

    int version = LDAP_VERSION3;
    ldap_set_option(ld, LDAP_OPT_PROTOCOL_VERSION, &version);

    /* Protect the bind credential in transit with StartTLS before binding */
    rc = ldap_start_tls_s(ld, NULL, NULL);
    if (rc != LDAP_SUCCESS) {
        ldap_unbind_ext_s(ld, NULL, NULL);
        return 0;
    }

    rc = ldap_simple_bind_s(ld, "cn=monitor-agent," BASE_DN, bind_pw);
    if (rc != LDAP_SUCCESS) {
        ldap_unbind_ext_s(ld, NULL, NULL);
        return 0;
    }

    struct timeval tv = {3, 0};
    rc = ldap_search_ext_s(ld, BASE_DN, LDAP_SCOPE_SUBTREE, filter,
                           NULL, 0, NULL, NULL, &tv, 10, &result);

    if (rc == LDAP_SUCCESS && ldap_count_entries(ld, result) > 0) {
        healthy = 1;
    }

    if (result) ldap_msgfree(result);
    ldap_unbind_ext_s(ld, NULL, NULL);
    return healthy;
}
